<?php get_header();the_post();$address=get_option('gmr_address');$hours=get_option('gmr_hours');$phone=get_option('gmr_public_phone');$email=get_option('gmr_public_email')?:get_option('gmr_inquiry_email',get_option('admin_email'));$map=get_option('gmr_map_url');?><header class="gmr-institution-hero"><div class="gmr-wrap"><span class="gmr-kicker">Contacto y visita</span><h1>Conversemos</h1><p>Visite la galeria o escribanos para consultar obras, artistas, certificaciones y proyectos curatoriales.</p></div></header><section class="gmr-section"><div class="gmr-wrap gmr-contact-grid"><div><span class="gmr-kicker">Visitenos</span><h2>Galeria Mayari Rojas</h2><dl><?php if($address):?><div><dt>Direccion</dt><dd><?php echo esc_html($address);?></dd></div><?php endif;?><?php if($hours):?><div><dt>Horario</dt><dd><?php echo esc_html($hours);?></dd></div><?php endif;?><?php if($phone):?><div><dt>Telefono</dt><dd><a href="tel:<?php echo esc_attr(preg_replace('/[^+0-9]/','',$phone));?>"><?php echo esc_html($phone);?></a></dd></div><?php endif;?><?php if($email):?><div><dt>Correo</dt><dd><a href="mailto:<?php echo esc_attr($email);?>"><?php echo esc_html($email);?></a></dd></div><?php endif;?></dl><?php if($map):?><a class="gmr-button" href="<?php echo esc_url($map);?>" target="_blank" rel="noopener">Abrir mapa</a><?php endif;?></div><div class="gmr-contact-note"><span class="gmr-kicker">Antes de su visita</span><p>Algunas obras y documentos se consultan con cita previa. Escribanos para preparar una seleccion acorde con sus intereses.</p><?php if($email):?><a class="gmr-button" href="mailto:<?php echo esc_attr($email);?>">Solicitar una cita</a><?php endif;?></div></div></section><?php get_footer();?>
